/** The layout for a pairing (either order) and variant, or null. */
export function findLayout11(dispA, dispB, variant) {
  const v = String(variant || 'A').toUpperCase();
  return LAYOUTS11.find(l => l.variant === v && l.attacker.disposition === dispA && l.defender.disposition === dispB)
    || LAYOUTS11.find(l => l.variant === v && l.attacker.disposition === dispB && l.defender.disposition === dispA) || null;
}
